import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int u, v;
        long cap, flow;
        long cst;
        Edge(int u, int v, long cap, long flow, long cst) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = flow;
            this.cst = cst;
        }
        long remaining() {
            return cap - flow;
        }
    }

    static int total_nodes;
    static List<Integer>[] adj;
    static List<Edge> all_edges;

    static void create_edge(int u, int v, long cap, long cst) {
        adj[u].add(all_edges.size());
        all_edges.add(new Edge(u, v, cap, 0, cst));
        adj[v].add(all_edges.size());
        all_edges.add(new Edge(v, u, 0, 0, -cst));
    }

    static long[] dist;
    static long total_cost;
    static int[] parent;
    static long[] flow_cap;
    static long total_flow;
    static boolean[] in_q;

    static void min_cost_max_flow(int s, int t) {
        Arrays.fill(in_q, false);
        total_flow = 0;
        total_cost = 0;
        while (true) {
            Arrays.fill(dist, Long.MAX_VALUE / 2);
            dist[s] = 0;
            Arrays.fill(parent, -1);
            parent[s] = 0;
            Arrays.fill(flow_cap, 0);
            flow_cap[s] = Long.MAX_VALUE / 2;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            in_q[s] = true;
            while (!q.isEmpty()) {
                int u = q.poll();
                in_q[u] = false;
                for (int idx : adj[u]) {
                    Edge e = all_edges.get(idx);
                    if (e.remaining() > 0 && dist[e.v] > dist[u] + e.cst + 1e-9) {
                        dist[e.v] = dist[u] + e.cst;
                        parent[e.v] = idx;
                        flow_cap[e.v] = Math.min(flow_cap[u], e.remaining());
                        if (!in_q[e.v]) {
                            q.offer(e.v);
                            in_q[e.v] = true;
                        }
                    }
                }
            }
            if (parent[t] < 0) break;
            long flow = flow_cap[t];
            total_flow += flow;
            total_cost += flow * dist[t];
            for (int v = t; v != s; v = all_edges.get(parent[v]).u) {
                Edge e = all_edges.get(parent[v]);
                e.flow += flow;
                all_edges.get(parent[v] ^ 1).flow -= flow;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        adj = new ArrayList[8200];
        for (int i = 0; i < adj.length; i++) {
            adj[i] = new ArrayList<>();
        }
        all_edges = new ArrayList<>();

        for (int i = 0; i < k; i++) {
            int x = Integer.parseInt(br.readLine()) - 1;
            create_edge(0, x + 1, 1, 0);
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken()) - 1;
            int y = Integer.parseInt(st.nextToken()) - 1;
            for (int i2 = 0; i2 < 105; i2++) {
                for (int j = 0; j < 51; j++) {
                    create_edge(i2 * n + x + 1, (i2 + 1) * n + y + 1, 1, c + d * (2 * j + 1));
                    create_edge(i2 * n + y + 1, (i2 + 1) * n + x + 1, 1, c + d * (2 * j + 1));
                }
            }
        }

        for (int i = 0; i < 105; i++) {
            for (int j = 0; j < n; j++) {
                create_edge(i * n + j + 1, (i + 1) * n + j + 1, 51, c);
            }
        }

        for (int i = 0; i < 105; i++) {
            create_edge(i * n + 1, 105 * n + 1, 51, 0);
        }

        total_nodes = 6 + 107 * n;
        dist = new long[total_nodes];
        parent = new int[total_nodes];
        flow_cap = new long[total_nodes];
        in_q = new boolean[total_nodes];

        min_cost_max_flow(0, 105 * n + 1);
        System.out.println(total_cost);
    }
}
